package io.archly.ai;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ai_usage_events") class AiUsageEvent {@Id UUID id;@Column(nullable=false,unique=true)String requestId;@Column(nullable=false)String userSubject;@Column(nullable=false)String model;@Column(nullable=false)long inputTokens;@Column(nullable=false)long outputTokens;@Column(nullable=false)long estimatedCostMicros;@Column(nullable=false)String status;@Column(nullable=false)Instant occurredAt; @Column(nullable=false)long cachedInputTokens; @Column(nullable=false)int providerAttempts; @Column(nullable=false)int repairAttempts; @Column(nullable=false)int unknownUsageAttempts; @Column(nullable=false)String pricingVersion="legacy-unversioned"; @Column(nullable=false)long durationMillis;protected AiUsageEvent(){}AiUsageEvent(String request,String user,String model,long input,long output,long cost,String status){id=UUID.randomUUID();requestId=request;userSubject=user;this.model=model;inputTokens=input;outputTokens=output;estimatedCostMicros=cost;this.status=status;occurredAt=Instant.now();}}
